62	// The MHPCO rounds in its own favour: premiums up, payouts down.
63	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
64	
65	const quote = (step: Step): QuoteResult => {
66	  const basePremium = policyBasePremium(step.items);
67	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
68	  const modifiedPremium = basePremium + firstInsuranceSurcharge;
69	
70	  return {
71	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
72	  };
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResult => ({
76	  results: scenario.steps.map(quote),
77	});
